class Gender(enum.Enum):
    
    FEMALE = 0
    
    MALE = 1
    


class _UniffiFfiConverterTypeGender(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return Gender.FEMALE
        if variant == 2:
            return Gender.MALE
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value == Gender.FEMALE:
            return
        if value == Gender.MALE:
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value == Gender.FEMALE:
            buf.write_i32(1)
        if value == Gender.MALE:
            buf.write_i32(2)



