    @staticmethod
    def check_lower(value):
        if value.is_ACK():
            _UniffiFfiConverterUInt8.check_lower(value.command)
            _UniffiFfiConverterUInt8.check_lower(value.status)
            return
        if value.is_BIND_START():
            _UniffiFfiConverterUInt32.check_lower(value.user_id)
            return
        if value.is_BIND_END():
            _UniffiFfiConverterBoolean.check_lower(value.first_bind)
            return
        if value.is_WATCH_ID():
            _UniffiFfiConverterString.check_lower(value.id)
            return
        if value.is_VERSION():
            _UniffiFfiConverterString.check_lower(value.text)
            _UniffiFfiConverterOptionalTypeFirmwareVersion.check_lower(value.parsed)
            return
        if value.is_BATTERY():
            _UniffiFfiConverterTypeBatteryStatus.check_lower(value.status)
            return
        if value.is_BRIGHTNESS():
            _UniffiFfiConverterUInt8.check_lower(value.level)
            _UniffiFfiConverterUInt8.check_lower(value.percent)
            return
        if value.is_SCREEN_TIMEOUT():
            _UniffiFfiConverterUInt8.check_lower(value.seconds)
            return
        if value.is_VIBRATION():
            _UniffiFfiConverterTypeVibrationSettings.check_lower(value.settings)
            return
        if value.is_VIBRATION_STRENGTH():
            _UniffiFfiConverterUInt8.check_lower(value.value)
            return
        if value.is_SWITCHES():
            _UniffiFfiConverterTypeSwitchStates.check_lower(value.states)
            _UniffiFfiConverterBytes.check_lower(value.raw)
            return
        if value.is_UNIT():
            _UniffiFfiConverterBoolean.check_lower(value.metric)
            return
        if value.is_UNITS_AND_FORMAT():
            _UniffiFfiConverterTypeUnitsAndFormat.check_lower(value.value)
            return
        if value.is_GOALS():
            _UniffiFfiConverterTypeGoals.check_lower(value.goals)
            return
        if value.is_GOAL6E():
            _UniffiFfiConverterTypeGoal6eKind.check_lower(value.kind)
            _UniffiFfiConverterUInt32.check_lower(value.value)
            return
        if value.is_SLEEP_WINDOW():
            _UniffiFfiConverterTypeSleepWindow.check_lower(value.window)
            return
        if value.is_INACTIVITY_ALERT():
            _UniffiFfiConverterTypeInactivityAlert.check_lower(value.alert)
            return
        if value.is_AUTO_HEART_RATE():
            _UniffiFfiConverterTypeAutoHeartRate.check_lower(value.value)
            return
        if value.is_DATA_COUNTS():
            _UniffiFfiConverterTypeDataCounts.check_lower(value.counts)
            return
        if value.is_SPORT_RECORDS():
            _UniffiFfiConverterSequenceTypeSportRecord.check_lower(value.records)
            return
        if value.is_SLEEP_POINTS():
            _UniffiFfiConverterSequenceTypeSleepPoint.check_lower(value.points)
            return
        if value.is_HEART_RATE_SAMPLES():
            _UniffiFfiConverterSequenceTypeHeartRateSample.check_lower(value.samples)
            return
        if value.is_WORKOUT_COUNT():
            _UniffiFfiConverterUInt16.check_lower(value.count)
            return
        if value.is_WORKOUTS():
            _UniffiFfiConverterSequenceTypeWorkoutRecord.check_lower(value.records)
            return
        if value.is_WORKOUT_HEART_RATE_COUNT():
            _UniffiFfiConverterUInt32.check_lower(value.count)
            return
        if value.is_WORKOUT_HEART_RATE():
            _UniffiFfiConverterSequenceTypeWorkoutHeartRateSample.check_lower(value.samples)
            return
        if value.is_COUNT6E():
            _UniffiFfiConverterUInt32.check_lower(value.count)
            return
        if value.is_SPORT_RECORD6E():
            _UniffiFfiConverterInt64.check_lower(value.timestamp)
            _UniffiFfiConverterUInt32.check_lower(value.steps)
            _UniffiFfiConverterUInt32.check_lower(value.calories)
